/**
 * EMITTED-PATTERN CENSUS
 * ======================
 *
 * Where do the generated bytes actually GO? Attributes every byte of a compiled
 * artifact to a normalised line shape, so the biggest repeated emissions are
 * ranked by TOTAL bytes rather than by how often they catch the eye.
 *
 * Normalisation: generated temporaries are `_name<N>` (see `v()` in codegen.ts),
 * so `_lf13` and `_lf20` are the same shape. Numeric literals and string
 * literals are also folded, otherwise every call site looks unique.
 */
import { join } from 'node:path'
import { gzipSync } from 'node:zlib'

const ROOT = join(import.meta.dirname, '..', '..')

const SPECS = [
  { id: 'example/json', module: '../../examples/json/parser.ts', exportName: 'jsonDoc' },
  { id: 'example/csv', module: '../../examples/csv/parser.ts', exportName: 'csvParser' },
  { id: 'example/graphql', module: '../../examples/graphql/parser.ts', exportName: 'graphqlDoc' },
  { id: 'example/css', module: '../../examples/css/parser.ts', exportName: 'Stylesheet' },
  { id: 'example/lang', module: '../../examples/lang/parser.ts', exportName: 'exprParser' },
  { id: 'example/jsonc', module: '../../examples/json/jsonc.ts', exportName: 'jsoncValue' },
  { id: 'example/jsonl', module: '../../examples/json/jsonl.ts', exportName: 'jsonl' },
]

function normalise(line: string): string {
  return line
    .trim()
    .replace(/\b_([A-Za-z]+)\d+\b/g, '_$1N')
    .replace(/\b\d+\b/g, 'K')
    .replace(/"(?:[^"\\]|\\.)*"/g, 'S')
    .replace(/'(?:[^'\\]|\\.)*'/g, 'S')
}

const { compile } = (await import(join(ROOT, 'src', 'index.ts'))) as { compile: (c: unknown) => { source: string } }

const totals = new Map<string, { count: number; bytes: number; sample: string }>()
let grandTotal = 0

const perFixture: { id: string; bytes: number; gzip: number }[] = []

for (const spec of SPECS) {
  const mod = (await import(join(import.meta.dirname, spec.module))) as Record<string, unknown>
  const gen = compile(mod[spec.exportName]).source
  perFixture.push({ id: spec.id, bytes: Buffer.byteLength(gen), gzip: gzipSync(gen).length })
  for (const line of gen.split('\n')) {
    const b = Buffer.byteLength(line) + 1
    grandTotal += b
    const key = normalise(line)
    if (key === '') continue
    const e = totals.get(key) ?? { count: 0, bytes: 0, sample: line.trim() }
    e.count++
    e.bytes += b
    totals.set(key, e)
  }
}

console.log('\nPER-FIXTURE TOTALS')
for (const f of perFixture) console.log(`  ${f.id.padEnd(20)} ${String(f.bytes).padStart(8)} B   gzip ${String(f.gzip).padStart(7)} B`)
console.log(`  ${'ALL'.padEnd(20)} ${String(grandTotal).padStart(8)} B`)

const ranked = [...totals.entries()].sort((a, b) => b[1].bytes - a[1].bytes)

console.log('\nTOP 30 LINE SHAPES BY TOTAL BYTES (across all fixtures)')
console.log('  ' + 'bytes'.padStart(8) + '  ' + 'pct'.padStart(5) + '  ' + 'count'.padStart(6) + '  shape')
let cum = 0
for (const [, e] of ranked.slice(0, 30)) {
  cum += e.bytes
  console.log('  ' + String(e.bytes).padStart(8) + '  ' + (100 * e.bytes / grandTotal).toFixed(2).padStart(5) + '  ' + String(e.count).padStart(6) + '  ' + e.sample.slice(0, 110))
}
console.log(`  -- top 30 = ${(100 * cum / grandTotal).toFixed(1)}% of all generated bytes`)

// Group the leaf-capture block specifically: it spans 5 lines per site.
const leafGate = ranked.find(([k]) => k.startsWith('if (_ctx._cstLeaves || _ctx._cstRawChildren) {'))
const leafObj = ranked.find(([k]) => k.startsWith('const _lfN = { _tag: S, value:'))
const leafPush1 = ranked.find(([k]) => k.startsWith('if (_ctx._cstLeaves) _ctx._cstLeaves.push'))
const leafPush2 = ranked.find(([k]) => k.startsWith('if (_ctx._cstRawChildren) _ctx._cstRawChildren.push'))
const parts = [leafGate, leafObj, leafPush1, leafPush2].filter(Boolean) as [string, { count: number; bytes: number }][]
if (parts.length) {
  const sites = leafObj?.[1].count ?? 0
  const blockBytes = parts.reduce((s, [, e]) => s + e.bytes, 0)
  // the closing `}` line is shared with every other block; charge 1 byte + indent ~ 7
  const closing = sites * 7
  console.log('\nLEAF-CAPTURE BLOCK (emitLeafCapture, codegen.ts:788)')
  console.log(`  sites: ${sites}`)
  console.log(`  bytes: ${blockBytes + closing}  (${(100 * (blockBytes + closing) / grandTotal).toFixed(2)}% of all generated bytes)`)
  console.log(`  per site: ${((blockBytes + closing) / sites).toFixed(0)} B`)
}
